/* mod_meet3.js  The meeting page (agenda with timer, invitees with quorum, live notes, actions, decisions, minutes, attachments, audit),
   the composer, action, decision and forum drawers, rescheduling with conflicts, and record-drawer link hooks. */
(function(){
const M=window.MEETX;if(!M||!M.hubReady)return;
const T=M.TYPES,E=esc,TODAY=M.TODAY,fd=M.fd,fdw=M.fdw,tm=M.tm,addD=M.addD,dOf=M.dOf,DN=M.DN;
const ME="Casey Rowan";
const tc=t=>"var("+((T[t]||{}).c||"--p4")+")";
const pl=(n,w)=>n+" "+w+(n===1?"":"s");
const hrsOpts=()=>{const o=[];for(let h=7;h<=18;h+=.5)o.push([String(h),tm(h)]);return o};
const ROOMS=["Teams","Webex","Aspen room (hybrid)","Boardroom","Casey's office","Cedar room","Phone bridge"];
const kindName={human:"Employee",ai:"AI agent",contractor:"Contractor",msp:"Managed service provider"};
const roleName={req:"Required",opt:"Optional",info:"Informational"};
const rsvpL={yes:"Accepted",maybe:"Maybe",no:"Declined",none:"No reply"};
const q$=s=>document.querySelector(s);

/* ---------- paint and refresh ---------- */
function paint(){const m=M.mById(S.meet.sel);const d=q$("#drawer");if(!m||!d)return;const sc=d.scrollTop;openDrawer(pageHTML(m));d.scrollTop=sc;const ins=d.querySelector(".dctl")}
function repaint(){render();if(S.meet.sel&&q$("#drawer")&&q$("#drawer").matches(":popover-open"))paint()}
M.repaint=repaint;
M.open=function(id){const m=M.mById(id);if(!m)return;if(S.screen==="fo"&&false)return;S.meet.sel=id;openDrawer(pageHTML(m));const d=q$("#drawer");if(d)d.scrollTop=0;audit("Meetings: opened meeting",m.t+" · "+fd(m.dt))};
M._open=M.open;
function other(){S.meet.sel=null}

/* ---------- quorum, local time ---------- */
function quorumView(m){const proj=m.st==="done"?m:Object.assign({},m,{inv:m.inv.map(x=>Object.assign({},x,{att:x.rsvp==="yes"?"present":null}))});return M.quorum(proj)}
function localTime(m,i){const z=i.tz||"ET";if(z==="ET")return tm(m.s)+" ET";const t=M.tzTime(m.s,"ET",z);return tm(t.h)+" "+z+(t.day?(t.day>0?" next day":" previous day"):"")}
function offHours(m,i){const z=i.tz||"ET";const t=M.tzTime(m.s,"ET",z),e=M.tzTime(m.e,"ET",z);return t.h<7.5||e.h>18.5||t.day!==0}

/* ---------- sections ---------- */
function headerHTML(m){const s=M.serById(m.series),live=m.live,state=m.cancel?["Cancelled","mute"]:live?["In progress","warn"]:m.st==="done"?["Held","good"]:["Upcoming","info"];
 const occ=s?` · occurrence ${(m.idx||0)+1} of ${(M.meetings().filter(x=>x.series===s.id).length)}`:"";
 return `<div class="meet-pg" style="--c:${tc(m.type)}"><div class="row">${M.tpill(m.type)}<span class="pill ${state[1]}">${state[0]}</span>${s?`<button class="chip" data-mt="ser|${s.id}">Repeats: ${E(s.cad)}${occ}</button>`:'<span class="pill mute">One-off</span>'}${m.exc?`<span class="pill warn">${E(m.exc)}</span>`:""}</div>
 <h2 style="font-size:30px;margin:10px 0 4px;padding-right:60px">${E(m.t)}</h2>
 <div class="muted">${fdw(m.dt)} · ${tm(m.s)} to ${tm(m.e)} Eastern · ${E(m.room||"No room")}${m.online?` · <a href="${E(m.online)}" target="_blank" rel="noopener" data-nodrag>Online link</a>`:""}</div>
 <dl class="kv"><dt>Chair</dt><dd>${m.chair?pchip(m.chair):"None"}</dd><dt>Secretary</dt><dd>${m.secy?pchip(m.secy):"None"}</dd></dl>
 <div class="row" style="margin:10px 0 4px">${!m.cancel&&m.st==="next"&&!m.live&&m.dt===TODAY?`<button class="btn primary" data-mt="start|${m.id}">Start meeting</button>`:""}${m.live?`<button class="btn primary" data-mt="end|${m.id}">End meeting and draft minutes</button>`:""}${m.st==="next"&&!m.cancel?`<button class="btn" data-mt="resched|${m.id}">Reschedule</button><button class="btn danger" data-mt="cancel|${m.id}">Cancel meeting</button>`:""}<button class="btn" data-mt="edit|${m.id}">Edit details</button><button class="btn quiet" data-mt="copy-meet|${m.id}">Copy to a new meeting</button>${m.d>=1&&m.d<=31?`<button class="btn quiet" data-go="fo:${m.id}">Open in First Officer calendar</button>`:""}</div>
 ${m.st==="next"&&!m.cancel?prepHTML(m):`<p class="story" data-role="story" style="margin:10px 0">${E(m.sum||"No summary yet. Add notes below and ask for one.")}</p><div class="row">${aiChip({model:"Claude Sonnet",conf:m.sum?.9:undefined,title:"Summary lineage",src:["Live notes","Agenda","Attendance","Decisions"],guards:["A person approves the minutes"]})}</div>`}</div>`}
function prepHTML(m){const b=M.prepBrief(m);return m.prep?`<div class="meet-prep"><div class="row"><b>Prep brief</b>${aiChip({model:"First Officer",conf:m.prep.conf,title:"Prep brief lineage",src:b.src,guards:["Reads only records you can see","You approve the agenda before it is sent"]})}<span class="muted small">drafted ${E(m.prep.at)}</span></div><p class="story" data-role="story">${E(b.txt)}</p><div class="row"><button class="btn quiet" data-mt="prep|${m.id}">Refresh brief</button>${!m.agenda.length?`<button class="btn" data-mt="agenda-tpl|${m.id}">Draft agenda from the template</button>`:""}</div></div>`:`<div class="meet-prep warn"><b>No prep brief yet.</b> <span class="muted small">${m.agenda.length?"":"There is no agenda either. "}First Officer can draft both from open actions, pending decisions and linked records.</span><div class="row" style="margin-top:6px"><button class="btn primary" data-mt="prep|${m.id}">Draft prep brief</button>${!m.agenda.length?`<button class="btn" data-mt="agenda-tpl|${m.id}">Draft agenda from the template</button>`:""}</div></div>`}
function elapsed(i){const t=S.meet.tm;if(!t)return 0;return (t.acc[i]||0)+(t.run===i?(Date.now()-t.t0)/1000:0)}
function clk(g,i){const s=elapsed(i),min=Math.floor(s/60),sec=Math.floor(s%60);return `<span class="meet-clk ${s>g.min*60?"over":""}" data-meet-clk="${i}" aria-live="off">${min}:${String(sec).padStart(2,"0")} of ${g.min}:00</span>`}
function agendaCard(m){const tot=m.agenda.reduce((a,g)=>a+g.min,0),len=Math.round((m.e-m.s)*60),tmr=S.meet.tm&&S.meet.tm.mid===m.id;
 return card("Agenda",tot?`${pl(m.agenda.length,"item")}, ${tot} of ${len} minutes planned${tot>len?". It overruns the slot.":"."}`:"No agenda yet.",`${m.agenda.length?`<div class="meet-agl2" data-dnd="ag:${m.id}" data-dnd-scope="meetag">${m.agenda.map((g,i)=>`<div class="meet-ag ${g.st}" data-dnd-id="${g.id}" tabindex="0"><i class="grip" aria-hidden="true"></i><div class="meet-agm"><b>${i+1}. ${E(g.t)}</b><span class="muted small">${avatar(g.own,{size:18})} ${E(g.own)} · ${g.min} min</span><input class="meet-bl" placeholder="Note for this item" value="${E(g.note||"")}" data-mt-in="agnote|${m.id}|${i}" aria-label="Note for ${E(g.t)}"></div><div class="meet-agc">${tmr||m.live||m.st==="done"?clk(g,i):""}${m.live||m.st==="next"?`<button class="btn quiet" data-mt="ag-timer|${m.id}|${i}">${S.meet.tm&&S.meet.tm.run===i&&S.meet.tm.mid===m.id?"Pause":"Start timer"}</button>`:""}<button class="btn quiet" data-mt="ag-done|${m.id}|${i}">${g.st==="done"?"Reopen":"Done"}</button><button class="btn quiet" data-mt="ag-del|${m.id}|${i}" aria-label="Remove item ${i+1}">Remove</button></div></div>`).join("")}</div>`:empty("No agenda","Draft one from the template or add items.")}<div class="row" style="margin-top:10px"><button class="btn" data-mt="ag-add|${m.id}">Add item</button>${!m.agenda.length?`<button class="btn" data-mt="agenda-tpl|${m.id}">Use the ${E(T[m.type].n.toLowerCase())} template</button>`:""}</div>`)}
function invitesCard(m){const q=quorumView(m),costP=M.cost(m,m.st==="next"),opts=DIR.filter(d=>!m.inv.some(i=>i.n===d.name)).map(d=>({v:d.name,l:d.name,sub:d.role,grp:({human:"Employees",ai:"AI agents",contractor:"Contractors",msp:"Managed service providers"})[d.kind]}));const pid="meet_inv_"+m.id;if(!S.mpSel[pid])S.mpSel[pid]=[];
 const mpc=mpHTML({id:pid,label:"Add people",all:"Pick people",opts});
 MPOPT[pid].onChange=sel=>{if(sel.length){sel.forEach(n=>{m.inv.push({n,role:"opt",rsvp:"none",att:null,dlg:"",tz:M.tzOf(n)});});M.maud(m,"Invitees added",sel.join(", "));m.att=m.inv.map(i=>i.n)}S.mpSel[pid]=[];setTimeout(paint,0)};
 return card("Invitees and attendance",`${pl(m.inv.length,"invitee")}. ${m.st==="done"?"Attendance is recorded.":"RSVPs update as people respond."} Cost ${m.st==="done"?"":"if all required and optional invitees attend "}about ${"$"+costP.cost.toLocaleString("en-US")} (${costP.hours.toFixed(1)} person hours).`,
 `${q?`<div class="meet-q ${q.met?"ok":"bad"}"><b>${m.st==="done"?"Quorum":"Projected quorum"}: ${q.met?"met":"not met"}</b><span class="small">${q.count} counted, ${q.min} needed. Required roles: ${q.roles.map(r=>`<span class="pill ${q.missing.includes(r)?"bad":"good"}">${E(r)}</span>`).join(" ")}</span><span class="muted small">Delegates count only if they hold the role. Agents do not count toward quorum.</span></div>`:'<p class="muted small">This meeting type has no quorum rule.</p>'}
 <div class="meet-invl">${m.inv.map((i,k)=>`<div class="meet-inv ${i.att==="absent"?"abs":""}"><div class="meet-ip">${pchip(i.n)} ${kindPill(M.kindOf(i.n))}</div><div class="meet-ic"><select class="fin meet-sel" data-mt-ch="role|${m.id}|${k}" aria-label="Requirement for ${E(i.n)}">${Object.keys(roleName).map(r=>`<option value="${r}" ${i.role===r?"selected":""}>${roleName[r]}</option>`).join("")}</select>
 <select class="fin meet-sel" data-mt-ch="rsvp|${m.id}|${k}" aria-label="RSVP for ${E(i.n)}">${Object.keys(rsvpL).map(r=>`<option value="${r}" ${i.rsvp===r?"selected":""}>${rsvpL[r]}</option>`).join("")}</select>
 <span class="meet-att">${["present","absent","delegate"].map(a=>`<button class="chip" data-mt="att|${m.id}|${k}|${a}" aria-pressed="${i.att===a}">${a[0].toUpperCase()+a.slice(1)}</button>`).join("")}</span>${i.att==="delegate"?`<span class="small">sends ${i.dlg?pchip(i.dlg):'<button class="chip" data-mt="dlg|'+m.id+"|"+k+'">pick delegate</button>'}</span>`:""}
 <span class="muted small ${offHours(m,i)?"meet-off":""}" title="Local time for this invitee">${localTime(m,i)}${offHours(m,i)?" (outside working hours)":""}</span><button class="btn quiet" data-mt="inv-del|${m.id}|${k}" aria-label="Remove ${E(i.n)}">Remove</button></div></div>`).join("")}</div>${mpc}`)}
function detect(txt){let a=0,d=0,r=0;(txt||"").split("\n").forEach(l=>{if(/^\s*@/.test(l))a++;if(/#decision\b/i.test(l))d++;if(/#risk\b/i.test(l))r++});return {a,d,r}}
const DOWN={mon:1,tue:2,wed:3,thu:4,fri:5,sat:6,sun:0};
function parseDue(s,base){s=(s||"").toLowerCase();let mm;if(/tomorrow/.test(s))return addD(base,1);if(/next week/.test(s))return addD(base,7);if(/end of (the )?week/.test(s))return nextDow(base,5);if(mm=s.match(/\b(mon|tue|wed|thu|fri|sat|sun)[a-z]*/))return nextDow(base,DOWN[mm[1]]);if(mm=s.match(/\b(oct|nov|dec|sep)[a-z]*\s+(\d{1,2})/)){const mo={sep:"09",oct:"10",nov:"11",dec:"12"}[mm[1]];return "2026-"+mo+"-"+String(mm[2]).padStart(2,"0")}return null}
function nextDow(base,n){let x=dOf(base);for(let k=1;k<=7;k++){if(M.dowOf(M.isoOf(x+k))===n)return M.isoOf(x+k)}return base}
function personIn(s){const t=s.trim();const full=DIR.find(d=>t.toLowerCase().startsWith(d.name.toLowerCase()));if(full)return full;const w=t.split(/\s+/)[0].replace(/[^A-Za-z]/g,"").toLowerCase();return DIR.find(d=>d.kind!=="msp"&&d.name.split(" ")[0].toLowerCase()===w)||null}
function parseNotes(m){const out=[],lines=(m.nt||"").split("\n");const have=new Set(M.allActs().filter(a=>a.mid===m.id).map(a=>a.t.toLowerCase()).concat(M.allDecs().filter(d=>d.mid===m.id).map(d=>d.t.toLowerCase())));
 lines.forEach((l,i)=>{const s=l.trim();if(!s||/^#\s/.test(s))return;let x;
  if(x=s.match(/#decision\b[:\s]*(.+)/i)){out.push({kind:"Decision",txt:x[1].trim(),own:"",due:"",conf:.93,line:i+1})}
  else if(x=s.match(/#risk\b[:\s]*(.+)/i)){out.push({kind:"Risk",txt:x[1].trim(),own:"",due:"",conf:.8,line:i+1})}
  else if(/^@/.test(s)){const p=personIn(s.slice(1));if(p){let rest=s.slice(1+((s.slice(1).toLowerCase().startsWith(p.name.toLowerCase()))?p.name.length:s.slice(1).split(/\s+/)[0].length)).trim().replace(/^to\s+/i,"");const by=rest.match(/\bby\s+(.+)$/i);const due=by?parseDue(by[1],m.dt):null;if(by)rest=rest.slice(0,by.index).trim();out.push({kind:"Action",txt:rest.charAt(0).toUpperCase()+rest.slice(1),own:p.name,due:due||addD(m.dt,7),conf:due?.94:.82,line:i+1})}}
  else if(x=s.match(/^(.*?)\b(will|to)\s+(confirm|send|share|draft|review|update|prepare|schedule|check|bring|close)\b(.*)$/i)){const p=personIn(x[1]);if(p&&x[1].trim().split(/\s+/).length<=3){const by=s.match(/\bby\s+(.+)$/i);out.push({kind:"Action",txt:(x[3]+x[4]).replace(/\bby\s+.+$/i,"").trim().replace(/^./,c=>c.toUpperCase()),own:p.name,due:by?parseDue(by[1],m.dt)||addD(m.dt,7):addD(m.dt,7),conf:.72,line:i+1})}}
  else if(/\b(we (agreed|decided)|agreed to|decision:)\b/i.test(s)){out.push({kind:"Decision",txt:s.replace(/^.*?(agreed to|decided to|decision:)\s*/i,"").replace(/^./,c=>c.toUpperCase()),own:"",due:"",conf:.7,line:i+1})}});
 return out.filter(p=>p.txt.length>5&&!have.has(p.txt.toLowerCase())).map((p,k)=>Object.assign(p,{id:m.id+"_x"+Date.now().toString(36)+k}))}
function notesCard(m){const dt=detect(m.nt),props=m.prop||[];
 return card("Live notes",m.live?"Notes are being taken now.":"Write freely. Start a line with @Name to assign an action, tag a line #decision to record a decision, and use a # heading for each topic.",
 `<div class="meet-tools"><button class="chip" data-mt="ins|${m.id}|# ">Heading</button><button class="chip" data-mt="ins|${m.id}|@">@ Assign an action</button><button class="chip" data-mt="ins|${m.id}|#decision ">#decision</button><button class="chip" data-mt="ins|${m.id}|#risk ">#risk</button></div>
 <textarea class="meet-notes" id="meet-notes" rows="12" data-mt-in="notes|${m.id}" placeholder="# Topic&#10;What was said...&#10;@Priya to confirm the acceptance criteria by Friday&#10;#decision Keep the Nov 13 beta date" aria-label="Meeting notes">${E(m.nt||"")}</textarea>
 <div class="meet-det muted small" data-meet-det>${detectHTML(dt)}</div>
 <div class="row" style="margin:10px 0"><button class="btn primary" data-mt="extract|${m.id}">Extract actions and decisions with AI</button><button class="btn" data-mt="sum|${m.id}">Write the summary</button></div>
 ${props.length?`<div class="eyebrow">Proposed by the AI, waiting for a person (${props.length})</div><div class="meet-rows">${props.map(p=>`<div class="meet-prop"><div><span class="pill ${p.kind==="Decision"?"info":p.kind==="Risk"?"bad":"warn"}">${p.kind}</span> <b>${E(p.txt)}</b><div class="muted small">${p.own?E(p.own)+" · ":""}${p.due?"due "+fd(p.due)+" · ":""}from note line ${p.line}</div>${aiChip({model:"Claude Sonnet",conf:p.conf,title:"Why this was proposed",src:["Note line "+p.line,"Attendee list","Directory"],guards:["A person accepts, edits or rejects every item","Confidence under 80% is flagged"]})}${p.conf<.8?'<span class="pill warn">Low confidence: check</span>':""}</div><div class="row"><button class="btn primary" data-mt="acc|${m.id}|${p.id}">Accept</button><button class="btn quiet" data-mt="rej|${m.id}|${p.id}">Reject</button></div></div>`).join("")}</div>${props.filter(p=>p.conf>=.85).length>1?`<button class="btn" data-mt="acc-all|${m.id}">Accept all with 85% confidence or more</button>`:""}`:""}`)}
const detectHTML=d=>`${pl(d.a,"@action line")}, ${pl(d.d,"#decision tag")}${d.r?", "+pl(d.r,"#risk tag"):""} in the notes.`;
function actionsCard(m){const A=M.allActs().filter(a=>a.mid===m.id);return card("Actions from this meeting",`${A.filter(M.isOpenA).length} open of ${A.length}. Closing one here also closes it in the RAID log.`,
 `${A.length?`<div class="meet-rows">${A.map(a=>`<div class="meet-act ${M.isLate(a)?"late":""}"><div><button class="meet-chk" data-mt="${a.st==="done"?"act-st|"+a.id+"|open":"act-done|"+a.id}" aria-label="${a.st==="done"?"Reopen":"Close"} ${a.id}" aria-pressed="${a.st==="done"}"></button></div><div class="meet-am"><button class="meet-rb" data-mt="act|${a.id}"><b>${E(a.t)}</b></button><span class="muted small">${a.id} · ${pchip(a.own)} · due ${fd(a.due)} · ${a.pri}${a.carry?` · carried ${a.carry}x`:""}${a.src==="ai"?` · AI ${Math.round(a.conf*100)}%`:""}</span><span class="row">${M.stPill(a)}${a.link?`<button class="chip" data-mt="lk|${a.link.k}|${a.link.id}">${E(a.link.id)}</button>`:""}${a.raid?`<button class="chip" data-mt="raid|${a.raid}">RAID ${E(a.raid)}</button>`:`<button class="chip" data-mt="act-raid|${a.id}">Add to RAID log</button>`}${M.isOpenA(a)?`<button class="chip" data-mt="carry|${a.id}">Carry over</button>`:""}</span></div></div>`).join("")}</div>`:empty("No actions yet","Assign one from the notes or add it here.")}<div class="row" style="margin-top:10px"><button class="btn" data-mt="add-act|${m.id}">Add action</button></div>`)}
function decisionsCard(m){const D=M.allDecs().filter(d=>d.mid===m.id);return card("Decisions from this meeting","Each decision keeps its rationale, the alternatives and who decided.",
 `${D.length?`<div class="meet-rows">${D.map(d=>`<div class="meet-dec"><button class="meet-rb" data-mt="dec|${d.id}"><b>${E(d.t)}</b></button><span class="muted small">${E(d.why)}</span><span class="muted small">${d.id} · decided by ${E(d.by)} · effective ${fd(d.eff)} · ${d.rev?"reversible":"not reversible"}${d.alts.length?" · considered: "+E(d.alts.join("; ")):""}</span><span class="row">${M.ratPill(d)}${d.rat==="pending"?`<button class="btn primary" data-mt="dec-rat|${d.id}|1">Ratify</button><button class="btn quiet" data-mt="dec-rat|${d.id}|0">Reject</button>`:""}${d.raid?`<button class="chip" data-mt="raid|${d.raid}">RAID ${E(d.raid)}</button>`:`<button class="chip" data-mt="dec-raid|${d.id}">Add to RAID log</button>`}${d.src==="ai"?aiChip({model:"Claude Sonnet",conf:d.conf,title:"Decision lineage",src:["Live notes"]}):""}</span></div>`).join("")}</div>`:empty("No decisions recorded","")}<div class="row" style="margin-top:10px"><button class="btn" data-mt="add-dec|${m.id}">Record a decision</button></div>`)}
function linksCard(m){const by={};(m.links||[]).forEach((l,i)=>{(by[l.k]=by[l.k]||[]).push(Object.assign({i},l))});
 const groups=Object.keys(by).map(k=>({key:k,label:M.LK[k][0]+"s",rows:by[k].map(l=>({id:l.id,t:M.linkLabel(l),sub:l.id,tag:M.LK[k][0],st:"info",go:()=>{M.linkGo(l)}}))}));
 return card("Linked records","What this meeting is about. The links show on the project, strategy item or ticket too.",`${groups.length?lrHTML({id:"meet-lk-"+m.id,groups,limit:5,search:false}):'<p class="muted">Not linked to anything yet.</p>'}${(m.links||[]).length?`<div class="row" style="margin-top:8px">${m.links.map((l,i)=>`<button class="chip" data-mt="lk-del|${m.id}|${i}" aria-label="Remove link to ${E(l.id)}">Remove ${E(l.id)}</button>`).join("")}</div>`:""}
 <label class="flab" style="margin-top:12px" for="meet-lks">Add a link</label><input class="fin" id="meet-lks" data-mt-in="lksearch|${m.id}" placeholder="Search projects, strategy items, incidents, changes, contracts, processes" autocomplete="off"><div class="meet-rows" data-meet-lkres>${lkResults(m,"")}</div>`)}
function lkResults(m,q){const have=new Set((m.links||[]).map(l=>l.k+":"+l.id));return M.linkables(q).filter(r=>!have.has(r.k+":"+r.id)).slice(0,q?10:6).map(r=>`<button class="meet-row" data-mt="lk-add|${m.id}|${r.k}|${E(r.id)}" style="--c:var(${M.LK[r.k][1]})"><span class="meet-tm"><small>${M.LK[r.k][0]}</small></span><span class="meet-rt"><b>${E(r.label)}</b><small>${E(r.id)}${r.sub?" · "+E(r.sub):""}</small></span><span class="meet-rx">Add</span></button>`).join("")||'<p class="muted small">No matches.</p>'}
function minutesCard(m){const mi=m.minutes||{st:"none"},steps=[["none","Not started"],["draft","Draft"],["review","In review"],["published","Published"]],ix=steps.findIndex(s=>s[0]===mi.st);
 const gov=!!(T[m.type]||{}).gov;
 return card("Minutes and distribution",gov?"Governance forum: the chair's approval is kept on record.":"Minutes go to everyone required or optional.",
 `<div class="meet-steps">${steps.map((s,i)=>`<span class="meet-stp ${i<=ix?"on":""}">${i+1}. ${s[1]}</span>`).join("")}</div>
 ${mi.st==="none"?`<p class="muted">${m.st==="done"?"Minutes have not been started.":"Minutes can be drafted once the meeting has been held."}</p>${m.st==="done"?`<button class="btn primary" data-mt="min-draft|${m.id}">Draft minutes from the notes</button>`:""}`:`<div class="meet-doc">${E(mi.text||M.minutesText(m))}</div><div class="row" style="margin:8px 0">${aiChip({model:"First Officer",conf:.9,title:"Minutes lineage",src:["Notes","Attendance","Decisions","Actions"],guards:["Chair approves before anything is sent"]})}</div>`}
 ${mi.st==="draft"?`<div class="row"><button class="btn primary" data-mt="min-submit|${m.id}">Send to ${E(m.chair||"the chair")} for approval</button><button class="btn" data-mt="min-draft|${m.id}">Regenerate</button></div>`:""}
 ${mi.st==="review"?`<div class="row"><button class="btn primary" data-mt="min-approve|${m.id}">Approve and publish as ${E(m.chair||"chair")}</button><button class="btn" data-mt="min-back|${m.id}">Request changes</button></div>`:""}
 ${mi.st==="published"?`<p class="muted small">Approved by ${E(mi.appr||m.chair)} on ${fd(mi.apprAt||mi.at)}. Sent to:</p><div class="row">${(mi.dist||[]).map(n=>pchip(n)).join("")}</div>`:""}
 ${m.st==="done"?`<div class="eyebrow" style="margin-top:14px">Follow-up email draft</div><div class="meet-doc">${E(M.followUp(m))}</div><div class="row"><button class="btn" data-mt="copy|${m.id}">Copy the email</button>${aiChip({model:"First Officer",conf:.86,title:"Follow-up lineage",src:["Minutes","Actions"],guards:["Never sent without approval"]})}</div>`:""}`)}
function filesCard(m){return card("Attachments and pre-reads","",`${(m.files||[]).length?`<div class="meet-rows">${m.files.map(f=>`<div class="meet-row"><span class="meet-tm"><small>${E(f.kind)}</small></span><span class="meet-rt"><b>${E(f.n)}</b><small>${E(f.size||"")} · added by ${E(f.by||"")}</small></span></div>`).join("")}</div>`:'<p class="muted">Nothing attached.</p>'}<div class="row" style="margin-top:8px"><button class="btn" data-mt="file-add|${m.id}">Attach a file</button></div>`)}
function auditCard(m){return card("Audit trail","Every change to this meeting.",`<ol class="meet-aud">${(m.aud||[]).slice(0,12).map(a=>`<li><b>${E(a.a)}</b> <span class="muted small">${E(a.d||"")} · ${E(a.by)} · ${E(a.at)}</span></li>`).join("")||"<li class='muted'>No changes recorded.</li>"}</ol>`)}
function pageHTML(m){return `${headerHTML(m)}<div class="dfullgrid">${agendaCard(m)}${invitesCard(m)}${notesCard(m)}${actionsCard(m)}${decisionsCard(m)}${linksCard(m)}${minutesCard(m)}${filesCard(m)}${auditCard(m)}</div>${procCard("meet_hub")}`}

/* ---------- timer ---------- */
setInterval(()=>{const t=S.meet.tm;if(!t||t.run==null)return;const m=M.mById(t.mid);if(!m)return;document.querySelectorAll("[data-meet-clk]").forEach(el=>{const i=+el.dataset.meetClk,g=m.agenda[i];if(!g)return;const s=elapsed(i);el.textContent=Math.floor(s/60)+":"+String(Math.floor(s%60)).padStart(2,"0")+" of "+g.min+":00";el.classList.toggle("over",s>g.min*60)})},1000);

/* ---------- forms ---------- */
const peopleOpts=()=>DIR.filter(d=>d.kind!=="msp"||true).slice(0,120).map(d=>[d.name,d.name+" ("+d.role+")"]);
function actForm(m,pre){openForm({id:"meet_actf",title:"Add an action",story:"The action is owned, dated and tied to this meeting. Pick a ticket or task to link, and it also goes to the RAID log if you ask.",submit:"Add action",
 fields:[{k:"t",label:"What needs to happen",type:"text",req:true,wide:true,ph:"Start with a verb",ai:{label:"Suggest from the notes",fn:()=>{const p=parseNotes(m)[0];return p?p.txt:"Confirm the next steps with the owner"}}},{k:"own",label:"Owner",type:"select",req:true,opts:peopleOpts()},{k:"due",label:"Due",type:"date",req:true},{k:"pri",label:"Priority",type:"chips",opts:["High","Medium","Low"]},
  {k:"lk",label:"Linked ticket or task (id)",type:"text",ph:"INC0412, CHG0312, p1_3",help:"Optional. Incident, change, problem, request or project task."},{k:"raid",label:"Also add to the RAID log",type:"toggle"}],
 live:v=>`${v.own?kindPill(M.kindOf(v.own))+" ":""}Will be assigned to <b>${E(v.own||"nobody yet")}</b>${v.due?", due "+fd(v.due):""}. Owners are reminded two days before and on the due date.`,
 defaults:Object.assign({own:m.chair||ME,due:addD(TODAY,7),pri:"Medium",raid:false},pre||{}),
 onSubmit:v=>{const lk=String(v.lk||"").trim();const k=/^INC/.test(lk)?"incident":/^CHG/.test(lk)?"change":/^PRB/.test(lk)?"problem":/^RITM/.test(lk)?"request":lk?"task":null;const a=M.addAction(m,{t:v.t,own:v.own,due:v.due,pri:v.pri,link:k?{k,id:lk}:null});if(v.raid)M.toRaid("act",a.id);setTimeout(repaint,0);return {toast:a.id+" added for "+v.own,audit:"action "+a.id}}})}
function decForm(m){openForm({id:"meet_decf",title:"Record a decision",story:"A decision needs a statement, the reason, what else was considered and who decided. Governance decisions then wait for ratification.",submit:"Record decision",
 fields:[{k:"t",label:"Decision",type:"longtext",req:true,wide:true,rows:2},{k:"why",label:"Rationale",type:"longtext",req:true,wide:true,rows:2},{k:"alts",label:"Alternatives considered (one per line)",type:"longtext",wide:true,rows:2},{k:"by",label:"Decider",type:"select",req:true,opts:peopleOpts()},{k:"eff",label:"Effective date",type:"date",req:true},{k:"rev",label:"Can it be reversed later",type:"toggle"},{k:"raid",label:"Add to the RAID log as a decision item",type:"toggle"}],
 live:v=>(T[m.type]||{}).gov?"This is a governance forum, so the decision will wait for ratification by the person or body in the charter.":"This forum does not need ratification.",
 defaults:{by:m.chair||ME,eff:addD(TODAY,3),rev:true,raid:true},
 onSubmit:v=>{const d=M.addDecision(m,{t:v.t,why:v.why,alts:String(v.alts||"").split("\n").map(x=>x.trim()).filter(Boolean),by:v.by,eff:v.eff,rev:!!v.rev,src:"manual"});if(v.raid)M.toRaid("dec",d.id);setTimeout(repaint,0);return {toast:d.id+" recorded",audit:"decision "+d.id}}})}
function editForm(m){openForm({id:"meet_editf",title:"Edit meeting details",submit:"Save",story:"Changing the chair or room is recorded in the audit trail. Date and time are changed with Reschedule.",
 fields:[{k:"t",label:"Title",type:"text",req:true,wide:true},{k:"chair",label:"Chair",type:"select",opts:peopleOpts()},{k:"secy",label:"Secretary",type:"select",opts:[["","None"]].concat(peopleOpts())},{k:"room",label:"Room",type:"select",opts:ROOMS.map(r=>[r,r])},{k:"online",label:"Online link",type:"text",ph:"https://"}],
 defaults:{t:m.t,chair:m.chair||"",secy:m.secy||"",room:m.room||"Teams",online:m.online||""},
 onSubmit:v=>{const ch=[];["t","chair","secy","room","online"].forEach(k=>{if((m[k]||"")!==(v[k]||"")){ch.push(k+": "+(m[k]||"none")+" to "+(v[k]||"none"));m[k]=v[k]}});if(ch.length)M.maud(m,"Details edited",ch.join("; "));setTimeout(()=>{S.meet.sel=m.id;repaint()},0);return {toast:"Meeting saved"}}})}
function cancelForm(m){openForm({id:"meet_cancelf",title:"Cancel "+m.t,submit:"Cancel meeting",story:"Invitees are told, open actions stay with their owners, and the cancellation is kept as an exception on the series.",fields:[{k:"why",label:"Reason",type:"text",req:true,wide:true,ph:"For example: no changes submitted"}],
 onSubmit:v=>{m.cancel=true;m.exc="Cancelled: "+v.why;M.maud(m,"Meeting cancelled",v.why+". "+m.inv.filter(i=>i.role!=="info").length+" people notified");M.sync();setTimeout(()=>{S.meet.sel=m.id;repaint()},0);return {toast:"Cancelled. Invitees notified."}}})}
function fileForm(m){openForm({id:"meet_filef",title:"Attach a file",submit:"Attach",story:"Pre-reads are sent with the invitation. Other files attach to the meeting and its linked records.",fields:[{k:"doc",label:"File",type:"file",req:true},{k:"kind",label:"Kind",type:"chips",opts:["Pre-read","Deck","Minutes","Recording","Other"]}],defaults:{kind:"Pre-read"},
 onSubmit:v=>{m.files.push({n:v.doc||"document.pdf",kind:v.kind||"Other",size:"0.4 MB",by:ME});M.maud(m,"File attached",v.doc);setTimeout(()=>{S.meet.sel=m.id;repaint()},0);return {toast:"Attached"}}})}
function agForm(m){openForm({id:"meet_agf",title:"Add an agenda item",submit:"Add",story:"Each item has one owner and a time box. The timer on the meeting page counts against it.",fields:[{k:"t",label:"Item",type:"text",req:true,wide:true},{k:"min",label:"Minutes",type:"number",min:1,max:120,req:true},{k:"own",label:"Owner",type:"select",opts:m.inv.map(i=>[i.n,i.n])}],defaults:{min:10,own:m.chair||(m.inv[0]||{}).n},
 onSubmit:v=>{m.agenda.push({id:m.id+"_g"+Date.now().toString(36),t:v.t,min:+v.min,own:v.own,note:"",st:"todo"});M.maud(m,"Agenda item added",v.t);setTimeout(()=>{S.meet.sel=m.id;repaint()},0);return {toast:"Item added"}}})}
function dlgForm(m,k){const i=m.inv[k];const alt=DIR.filter(d=>d.kind==="human"&&!m.inv.some(x=>x.n===d.name)).slice(0,60);openForm({id:"meet_dlgf",title:"Delegate for "+i.n,submit:"Set delegate",story:"A delegate counts toward quorum only if they hold the same role.",fields:[{k:"d",label:"Delegate",type:"select",req:true,opts:alt.map(d=>[d.name,d.name+" ("+d.role+")"]),ph:"Pick a person"}],
 onSubmit:v=>{i.dlg=v.d;i.att="delegate";M.maud(m,"Delegate named",i.n+" sends "+v.d);setTimeout(()=>{S.meet.sel=m.id;repaint()},0);return {toast:v.d+" will attend for "+i.n}}})}
M.reschedDrawer=function(id,dt,cf){const m=M.mById(id);const s=M.serById(m.series);S.meet.rs={id,dt,s:m.s,scope:"one"};
 const paintR=()=>{const r=S.meet.rs,cfl=M.conflicts(m,r.dt,r.s);openDrawer(`<span class="pill info">Reschedule</span><h2 style="font-size:26px;margin:10px 0 6px;padding-right:60px">${E(m.t)}</h2><p class="story" data-role="story">From ${fdw(m.dt)} ${tm(m.s)} to <b>${fdw(r.dt)} ${tm(r.s)}</b>.</p>
  ${cfl.length?`<div class="meet-q bad"><b>${pl(cfl.length,"conflict")}</b>${cfl.map(c=>`<span class="small">${E(c.m.t)} at ${tm(c.m.s)} to ${tm(c.m.e)}: ${c.people.length?E(c.people.join(", "))+" "+(c.people.length>1?"are":"is")+" also invited":""}${c.room?" the room is booked":""}</span>`).join("")}</div>`:'<div class="meet-q ok"><b>No conflicts</b><span class="small">Required invitees and the room are free.</span></div>'}
  <div class="fld"><label class="flab" for="meet-rs-d">Date</label><input class="fin" type="date" id="meet-rs-d" value="${r.dt}" data-mt-ch="rs-d"></div><div class="fld"><label class="flab" for="meet-rs-t">Start time</label><select class="fin" id="meet-rs-t" data-mt-ch="rs-t">${hrsOpts().map(o=>`<option value="${o[0]}" ${+o[0]===r.s?"selected":""}>${o[1]}</option>`).join("")}</select></div>
  ${s?`<div class="eyebrow" style="margin-top:12px">Which meetings</div><div class="row"><button class="chip" data-mt="rs-scope|one" aria-pressed="${r.scope==="one"}">Only this one (creates an exception)</button><button class="chip" data-mt="rs-scope|all" aria-pressed="${r.scope==="all"}">This and all later ones in the series</button></div>`:""}
  <div class="row" style="margin-top:16px"><button class="btn primary" data-mt="rs-go">${cfl.length?"Move anyway":"Move"}</button><button class="btn" data-mt="rs-no">Keep as is</button></div>`)};
 S.meet.rsPaint=paintR;paintR()};
M.resched=function(id){const m=M.mById(id);M.reschedDrawer(id,m.dt,[])};

/* ---------- action, decision and forum drawers ---------- */
M.actDrawer=function(id){const a=M.aById(id);if(!a)return;other();const m=M.mById(a.mid)||{};
 const g=[{key:"mtg",label:"Source meeting",rows:[{id:m.id,t:m.t,sub:fd(m.dt),tag:"Meeting",st:"info",go:()=>M.open(m.id)}]}].concat(a.link?[{key:"tk",label:"Linked "+(a.link.k==="task"?"task":"ticket"),rows:[{id:a.link.id,t:M.linkLabel(a.link),sub:a.link.id,tag:M.LK[a.link.k]?M.LK[a.link.k][0]:"Task",st:"info",go:()=>M.linkGo(a.link)}]}]:[]).concat(a.raid?[{key:"rd",label:"RAID log",rows:[{id:a.raid,t:"Issue item "+a.raid,sub:"Linked both ways",tag:"RAID",st:"info",go:()=>window.ppmOpenRaid&&window.ppmOpenRaid(a.raid)}]}]:[]);
 openDrawer(`<div class="row"><span class="pill mute">${a.id}</span>${M.stPill(a)}<span class="pill ${a.pri==="High"?"warn":"mute"}">${a.pri}</span>${a.carry?`<span class="pill ${a.carry>1?"bad":"warn"}">Carried over ${a.carry}x</span>`:""}</div><h2 style="font-size:26px;margin:10px 0 6px;padding-right:60px">${E(a.t)}</h2>
 <div class="dfullgrid"><dl class="kv"><dt>Owner</dt><dd>${pchip(a.own)} ${kindPill(M.kindOf(a.own))}</dd><dt>Due</dt><dd>${fd(a.due,1)}${M.isLate(a)?` <span class="pill bad">${dOf(TODAY)-dOf(a.due)} days late</span>`:""}</dd><dt>Created</dt><dd>${fd(a.created)}${M.isOpenA(a)?" · open "+(dOf(TODAY)-dOf(a.created))+" days":""}</dd>${a.closed?`<dt>Closed</dt><dd>${fd(a.closed)}</dd>`:""}<dt>Source</dt><dd>${a.src==="ai"?"Proposed by AI at "+Math.round(a.conf*100)+"%, accepted by a person":a.src==="manual"?"Added by hand":"From the notes"}</dd></dl><div><div class="eyebrow">Linked records</div>${lrHTML({id:"meet-al-"+a.id,groups:g,limit:5,search:false})}</div></div>
 <div class="row" style="margin-top:14px">${M.isOpenA(a)?`<button class="btn primary" data-mt="act-done|${a.id}">Close action</button>`:`<button class="btn" data-mt="act-st|${a.id}|open">Reopen</button>`}${a.st==="open"?`<button class="btn" data-mt="act-st|${a.id}|prog">Start</button>`:""}${M.isOpenA(a)&&a.st!=="blocked"?`<button class="btn" data-mt="act-st|${a.id}|blocked">Mark blocked</button>`:""}${M.isOpenA(a)?`<button class="btn" data-mt="carry|${a.id}">Carry to next meeting</button>`:""}${!a.raid?`<button class="btn" data-mt="act-raid|${a.id}">Add to RAID log</button>`:""}</div>`);audit("Meetings: opened action",a.id)};
M.decDrawer=function(id){const d=M.dById(id);if(!d)return;other();const m=M.mById(d.mid)||{};
 const g=[{key:"mtg",label:"Source meeting",rows:[{id:m.id,t:m.t,sub:fd(m.dt),tag:"Meeting",st:"info",go:()=>M.open(m.id)}]}].concat((d.links||[]).length?[{key:"lk",label:"Applies to",rows:d.links.map(l=>({id:l.id,t:M.linkLabel(l),sub:l.id,tag:(M.LK[l.k]||[l.k])[0],st:"info",go:()=>M.linkGo(l)}))}]:[]).concat(d.raid?[{key:"rd",label:"RAID log",rows:[{id:d.raid,t:"Decision item "+d.raid,sub:"Linked both ways",tag:"RAID",st:"info",go:()=>window.ppmOpenRaid&&window.ppmOpenRaid(d.raid)}]}]:[]);
 openDrawer(`<div class="row"><span class="pill mute">${d.id}</span>${M.ratPill(d)}<span class="pill ${d.rev?"mute":"warn"}">${d.rev?"Reversible":"Not reversible"}</span></div><h2 style="font-size:26px;margin:10px 0 6px;padding-right:60px">${E(d.t)}</h2><p class="story" data-role="story">${E(d.why)}</p>
 <div class="dfullgrid"><dl class="kv"><dt>Decided by</dt><dd>${pchip(d.by)}</dd><dt>Decided</dt><dd>${fd(d.dt,1)}</dd><dt>Effective</dt><dd>${fd(d.eff,1)}</dd><dt>Alternatives</dt><dd>${d.alts.length?d.alts.map(x=>`<span class="pill mute">${E(x)}</span>`).join(" "):"None recorded"}</dd>${d.ratAt?`<dt>Ratified</dt><dd>${E(d.ratBy)} on ${fd(d.ratAt)}</dd>`:""}<dt>Recorded</dt><dd>${d.src==="ai"?"Proposed by AI at "+Math.round(d.conf*100)+"%, accepted by a person":"By a person"}</dd></dl><div><div class="eyebrow">Linked records</div>${lrHTML({id:"meet-dl-"+d.id,groups:g,limit:5,search:false})}</div></div>
 <div class="row" style="margin-top:14px">${d.rat==="pending"?`<button class="btn primary" data-mt="dec-rat|${d.id}|1">Ratify</button><button class="btn danger" data-mt="dec-rat|${d.id}|0">Reject</button>`:""}${!d.raid?`<button class="btn" data-mt="dec-raid|${d.id}">Add to RAID log</button>`:""}</div>`);audit("Meetings: opened decision",d.id)};
M.serDrawer=function(id){const s=M.serById(id);if(!s)return;other();const h=M.health(s),q=(T[s.type]||{}).quorum,ms=M.meetings().filter(x=>x.series===s.id).sort((a,b)=>a.dt<b.dt?-1:1);
 const g=[{key:"occ",label:"Meetings in this series",rows:ms.slice(-14).reverse().map(m=>({id:m.id,t:m.t+" · "+fd(m.dt),sub:m.exc||(m.st==="done"?"Held":"Upcoming"),tag:m.cancel?"Cancelled":m.st==="done"?"Held":"Next",st:m.cancel?"mute":m.exc?"warn":"info",go:()=>M.open(m.id)}))}];
 openDrawer(`<div class="row">${M.tpill(s.type)}${s.scaled?"":'<span class="pill info">Charter</span>'}</div><h2 style="font-size:28px;margin:10px 0 6px;padding-right:60px">${E(s.n)}</h2><p class="story" data-role="story">${E(s.purpose)}</p>
 <div class="dfullgrid"><div><dl class="kv"><dt>Chair</dt><dd>${pchip(s.chair)}</dd>${s.secy?`<dt>Secretary</dt><dd>${pchip(s.secy)}</dd>`:""}<dt>Cadence</dt><dd>${E(s.cad)}</dd><dt>Quorum</dt><dd>${q?q.min+" people including "+E(q.roles.join(" and ")):"No quorum rule"}</dd><dt>Decision rights</dt><dd>${E(s.rights)}</dd><dt>Escalation path</dt><dd>${E(s.esc||"None")}</dd></dl>
 <div class="eyebrow" style="margin-top:12px">Members</div><div class="row">${s.mem.map(x=>`<span class="meet-mem">${pchip(x[0])}<small>${roleName[x[1]]}</small></span>`).join("")}</div></div>
 <div><div class="eyebrow">Health</div><div class="statrow">${kpi("Attendance",h.att==null?"n/a":h.att+"%","required, held meetings",{metric:"m_meet_attendance"})}${kpi("Actions closed on time",h.clo==null?"n/a":h.clo+"%","due to date",{metric:"m_meet_actions_closed"})}${kpi("Days to ratify",h.lat==null?"n/a":h.lat.toFixed(1),"decision to ratification",{metric:"m_meet_decision_latency"})}${kpi("Cost, 30 days","$"+Math.round(h.cost).toLocaleString("en-US"),pl(h.held,"held meeting"),{metric:"m_meet_cost",keep:1})}</div>
 <p class="story" data-role="story" style="margin-top:10px">${h.att!=null&&h.att<90?`Attendance of ${h.att}% is under the 90% target. Check the time slot and trim the required list before the next meeting.`:"Attendance is on target."} ${h.openA} open actions and ${h.dec} decisions came from this forum.</p></div></div>
 <div style="margin-top:12px"><div class="eyebrow">Occurrences and exceptions</div>${lrHTML({id:"meet-sl-"+s.id,groups:g,limit:6,search:false})}</div>
 <div class="row" style="margin-top:14px">${s.scaled?"":`<button class="btn primary" data-mt="ser-edit|${s.id}">Edit the charter</button>`}<button class="btn" data-mt="ser-next|${s.id}">Schedule the next meeting</button></div>`);audit("Meetings: opened forum",s.n)};
function serForm(s){const q=(T[s.type]||{}).quorum||{min:0,roles:[]};openForm({id:"meet_serf",title:"Edit charter: "+s.n,submit:"Save charter",story:"The charter is the rule book for the forum. Changes are audited and shown on every meeting in the series.",
 fields:[{k:"purpose",label:"Purpose",type:"longtext",wide:true,rows:2,req:true},{k:"chair",label:"Chair",type:"select",opts:peopleOpts()},{k:"secy",label:"Secretary",type:"select",opts:[["","None"]].concat(peopleOpts())},{k:"cad",label:"Cadence",type:"text"},{k:"min",label:"Quorum minimum",type:"number",min:0,max:12},{k:"rights",label:"Decision rights",type:"longtext",wide:true,rows:2},{k:"esc",label:"Escalation path",type:"text",wide:true}],
 defaults:{purpose:s.purpose,chair:s.chair,secy:s.secy||"",cad:s.cad,min:q.min,rights:s.rights,esc:s.esc},
 onSubmit:v=>{Object.assign(s,{purpose:v.purpose,chair:v.chair,secy:v.secy,cad:v.cad,rights:v.rights,esc:v.esc});if(T[s.type].quorum)T[s.type].quorum.min=+v.min;audit("Meetings: charter edited",s.n);M.sync();setTimeout(()=>{M.serDrawer(s.id);render()},0);return {toast:"Charter saved",close:false}}})}

/* ---------- composer ---------- */
function newDraft(pre){pre=pre||{};const ty=pre.type||"design",Tm=T[ty];const d={type:ty,title:pre.title||Tm.n,dt:pre.dt||addD(TODAY,1),s:pre.s||10,dur:Tm.dur,room:pre.room||"Teams",online:true,rep:"none",repN:4,ser:"",inv:[{n:ME,role:"req"}],ag:Tm.ag.map(a=>({t:a[0],min:a[1],own:ME})),links:[],files:[],prep:true,fromSeries:""};(pre.people||[]).forEach(n=>{if(!d.inv.some(i=>i.n===n))d.inv.push({n,role:"req"})});return d}
M.compose=function(pre){S.meet.draft=newDraft(pre);S.meet.sel=null;paintComposer(true)};
function draftConf(d){const mine=d.inv.filter(i=>i.role!=="info").map(i=>i.n);const fake={id:"draft",s:+d.s,e:+d.s+d.dur,inv:d.inv.map(i=>Object.assign({},i)),room:d.room};return M.conflicts(fake,d.dt,+d.s)}
function draftCost(d){let c=0;d.inv.forEach(i=>{if(i.role!=="info"||M.kindOf(i.n)==="ai")c+=M.rateOf(i.n)*d.dur});return Math.round(c)}
function composerHTML(){const d=S.meet.draft,Tm=T[d.type],cf=draftConf(d),cost=draftCost(d);
 const opts=DIR.filter(p=>!d.inv.some(i=>i.n===p.name)).map(p=>({v:p.name,l:p.name,sub:p.role,grp:({human:"Employees",ai:"AI agents",contractor:"Contractors",msp:"Managed service providers"})[p.kind]}));const pid="meet_inv_draft";if(!S.mpSel[pid])S.mpSel[pid]=[];
 const picker=mpHTML({id:pid,label:"Add people from the directory",all:"Pick people",opts});MPOPT[pid].onChange=sel=>{sel.forEach(n=>{if(!d.inv.some(i=>i.n===n))d.inv.push({n,role:"req"})});S.mpSel[pid]=[];setTimeout(()=>paintComposer(),0)};
 const tzs={};d.inv.forEach(i=>{const z=M.tzOf(i.n);tzs[z]=(tzs[z]||0)+1});const off=d.inv.filter(i=>{const z=M.tzOf(i.n);const t=M.tzTime(+d.s,"ET",z),e=M.tzTime(+d.s+d.dur,"ET",z);return t.h<7.5||e.h>18.5||t.day!==0});
 const q=Tm.quorum;const reqN=d.inv.filter(i=>i.role==="req"&&M.kindOf(i.n)!=="ai");const miss=q?q.roles.filter(r=>!reqN.some(i=>((who(i.n)||{}).role||"").toLowerCase().includes(r.toLowerCase()))):[];
 const lkq=(S.meet.lkq||"");
 return `<form class="fform meet-comp" onsubmit="return false"><h3 class="ftitle">New meeting</h3><p class="muted fstory" data-role="story">Pick a template, add the people who must be there, link what it is about, and check the conflicts. Nothing is sent until you press Schedule.</p>
 <div class="fgrid"><div class="fld wide"><span class="flab">Type (template)</span><div class="fchips">${Object.keys(T).map(k=>`<button type="button" class="chip" data-mt="df-type|${k}" aria-pressed="${d.type===k}" style="--c:${tc(k)}"><i class="dot" style="background:${tc(k)}"></i>${T[k].n}</button>`).join("")}</div><small class="fhelp">${E(Tm.n)}: ${Tm.ag.length} agenda items, ${Math.round(Tm.dur*60)} minutes${q?", quorum of "+q.min+" including "+q.roles.join(" and "):", no quorum rule"}.</small></div>
 <div class="fld wide"><label class="flab" for="df-title">Title</label><input class="fin" id="df-title" value="${E(d.title)}" data-mt-in="df|title" autocomplete="off"></div>
 <div class="fld"><label class="flab" for="df-dt">Date</label><input class="fin" type="date" id="df-dt" value="${d.dt}" data-mt-ch="df|dt"></div>
 <div class="fld"><label class="flab" for="df-s">Start (Eastern)</label><select class="fin" id="df-s" data-mt-ch="df|s">${hrsOpts().map(o=>`<option value="${o[0]}" ${+o[0]===+d.s?"selected":""}>${o[1]}</option>`).join("")}</select></div>
 <div class="fld"><span class="flab">Length</span><div class="fchips">${[[.25,"15 min"],[.5,"30 min"],[.75,"45 min"],[1,"1 hour"],[1.5,"90 min"]].map(x=>`<button type="button" class="chip" data-mt="df-dur|${x[0]}" aria-pressed="${d.dur===x[0]}">${x[1]}</button>`).join("")}</div></div>
 <div class="fld"><label class="flab" for="df-room">Room</label><select class="fin" id="df-room" data-mt-ch="df|room">${ROOMS.map(r=>`<option ${d.room===r?"selected":""}>${r}</option>`).join("")}</select><small class="fhelp">${/Teams|Webex|bridge/.test(d.room)?"An online link is created.":"A room booking is requested, plus an online link if you turn it on."}</small></div>
 <div class="fld"><span class="flab">Repeat</span><div class="fchips">${[["none","Does not repeat"],["weekly","Weekly"],["biweekly","Every other week"],["monthly","Monthly"]].map(x=>`<button type="button" class="chip" data-mt="df-rep|${x[0]}" aria-pressed="${d.rep===x[0]}">${x[1]}</button>`).join("")}</div>${d.rep!=="none"?`<small class="fhelp">Creates a series of ${d.repN} meetings. Each can be moved or cancelled on its own as an exception.</small>`:""}</div>
 <div class="fld wide"><span class="flab">Invitees (${d.inv.length})</span>${picker}<div class="meet-invl">${d.inv.map((i,k)=>`<div class="meet-inv"><div class="meet-ip">${pchip(i.n)} ${kindPill(M.kindOf(i.n))}</div><div class="meet-ic"><span class="fchips">${Object.keys(roleName).map(r=>`<button type="button" class="chip" data-mt="df-role|${k}|${r}" aria-pressed="${i.role===r}">${roleName[r]}</button>`).join("")}</span><span class="muted small">${tm(M.tzTime(+d.s,"ET",M.tzOf(i.n)).h)} ${M.tzOf(i.n)}</span><button type="button" class="btn quiet" data-mt="df-del|${k}" aria-label="Remove ${E(i.n)}">Remove</button></div></div>`).join("")}</div></div>
 <div class="fld wide"><span class="flab">Agenda</span>${d.ag.map((a,k)=>`<div class="meet-agr"><input class="fin" value="${E(a.t)}" data-mt-in="df-ag|${k}|t" aria-label="Item ${k+1}"><input class="fin" type="number" min="1" max="120" value="${a.min}" data-mt-in="df-ag|${k}|min" aria-label="Minutes for item ${k+1}"><select class="fin" data-mt-ch="df-ag|${k}|own" aria-label="Owner of item ${k+1}">${d.inv.map(i=>`<option ${i.n===a.own?"selected":""}>${E(i.n)}</option>`).join("")}</select><button type="button" class="btn quiet" data-mt="df-agdel|${k}" aria-label="Remove item ${k+1}">Remove</button></div>`).join("")}<button type="button" class="btn" data-mt="df-agadd">Add item</button><small class="fhelp">${d.ag.reduce((x,a)=>x+(+a.min||0),0)} of ${Math.round(d.dur*60)} minutes planned.</small></div>
 <div class="fld wide"><span class="flab">What is it about (links)</span><div class="row">${d.links.map((l,k)=>`<button type="button" class="chip" data-mt="df-lkdel|${k}" aria-label="Remove ${E(l.id)}">${M.LK[l.k][0]}: ${E(l.id)} ×</button>`).join("")||'<span class="muted small">Nothing linked yet.</span>'}</div><input class="fin" id="df-lks" value="${E(lkq)}" data-mt-in="df-lks" placeholder="Search projects, strategy items, incidents, changes, contracts, processes" autocomplete="off"><div class="meet-rows" data-meet-dflk>${dfLinkRes(lkq)}</div></div>
 <div class="fld wide"><span class="flab">Pre-read attachments</span><div class="row">${d.files.map((f,k)=>`<span class="chip">${E(f)}</span>`).join("")||'<span class="muted small">None</span>'}</div><label class="fdrop" for="df-file"><input type="file" class="sr" id="df-file" data-mt-ch="df-file"><span><b>Choose a file or drop it here</b><small>Sent with the invitation as a pre-read.</small></span></label></div>
 <div class="fld wide"><button type="button" class="ftog" role="switch" aria-checked="${!!d.prep}" data-mt="df-prep"><i></i><span>${d.prep?"First Officer drafts a prep brief 48 hours ahead":"No prep brief"}</span></button></div></div>
 <div class="flive meet-live">${cf.length?`<div class="meet-q bad"><b>${pl(cf.length,"conflict")}</b>${cf.slice(0,3).map(c=>`<span class="small">${E(c.m.t)} at ${tm(c.m.s)}: ${c.people.slice(0,3).map(E).join(", ")||"room booked"}</span>`).join("")}</div>`:'<div class="meet-q ok"><b>No conflicts</b><span class="small">Required invitees are free at this time.</span></div>'}
 ${miss.length?`<div class="meet-q bad"><b>Quorum at risk</b><span class="small">No required invitee holds the role: ${miss.map(E).join(", ")}.</span></div>`:""}
 ${off.length?`<div class="meet-q warn"><b>Time zones</b><span class="small">${off.map(i=>E(i.n)+" ("+M.tzOf(i.n)+")").join(", ")} would be outside working hours.</span></div>`:""}
 <p class="story" data-role="story">Estimated cost <b>$${cost.toLocaleString("en-US")}</b> for ${d.inv.filter(i=>i.role!=="info").length} people. ${d.inv.filter(i=>i.role==="opt").length?"Making the "+d.inv.filter(i=>i.role==="opt").length+" optional invitees informational would save about $"+Math.round(d.inv.filter(i=>i.role==="opt").reduce((x,i)=>x+M.rateOf(i.n)*d.dur,0)).toLocaleString("en-US")+".":""}</p></div>
 <div class="fact"><button type="button" class="btn primary" data-mt="df-go">Schedule</button><button type="button" class="btn" data-mt="df-cancel">Discard</button></div></form>`}
function dfLinkRes(q){const d=S.meet.draft,have=new Set(d.links.map(l=>l.k+":"+l.id));return M.linkables(q).filter(r=>!have.has(r.k+":"+r.id)).slice(0,q?8:5).map(r=>`<button type="button" class="meet-row" data-mt="df-lkadd|${r.k}|${E(r.id)}" style="--c:var(${M.LK[r.k][1]})"><span class="meet-tm"><small>${M.LK[r.k][0]}</small></span><span class="meet-rt"><b>${E(r.label)}</b><small>${E(r.id)}</small></span><span class="meet-rx">Add</span></button>`).join("")||'<p class="muted small">No matches.</p>'}
function paintComposer(first){const d=q$("#drawer");const sc=d?d.scrollTop:0;openDrawer(composerHTML());if(d&&!first)d.scrollTop=sc}
function createFromDraft(){const d=S.meet.draft;if(!d.title.trim()){toast("Give the meeting a title","warn");return}if(d.inv.filter(i=>i.role!=="info").length<2){toast("Invite at least one other person","warn");return}
 const n=d.rep==="none"?1:d.repN,step=d.rep==="weekly"?7:d.rep==="biweekly"?14:28;let ser=null;
 if(d.rep!=="none"){ser={id:"sr_u"+Date.now().toString(36),n:d.title,type:d.type,chair:ME,secy:"",cad:({weekly:"Weekly",biweekly:"Every other week",monthly:"Monthly"})[d.rep]+", "+DN[M.dowOf(d.dt)]+" "+tm(+d.s),s:+d.s,e:+d.s+d.dur,room:d.room,purpose:"Created from a template on "+fd(TODAY)+".",rights:"To be set by the chair.",esc:"",mem:d.inv.map(i=>[i.n,i.role]),dates:[],mids:{},ex:{},links:d.links.map(l=>[l.k,l.id])};M.series.push(ser)}
 let first=null;for(let k=0;k<n;k++){const dt=addD(d.dt,k*step);if(ser)ser.dates.push(dt);
  const m=M.addMeeting({t:d.title,type:d.type,series:ser?ser.id:"",dt,s:+d.s,e:+d.s+d.dur,room:d.room,online:/Teams|Webex|bridge/.test(d.room)||d.online?"https://teams.example/meet/"+Date.now().toString(36)+k:"",inv:d.inv.map(i=>({n:i.n,role:i.role,rsvp:i.n===ME?"yes":"none",att:null,dlg:"",tz:M.tzOf(i.n)})),links:d.links.map(l=>({k:l.k,id:l.id})),chair:ME,secy:"",st:"next",
   agenda:d.ag.map((a,i)=>({id:"",t:a.t,min:+a.min,own:a.own,note:"",st:"todo"})),files:d.files.map(f=>({n:f,kind:"Pre-read",size:"0.4 MB",by:ME})),prep:d.prep?{at:"Oct 6 "+tm(M.NOWH),conf:.84}:null,idx:k,occ:k+1});
  m.agenda.forEach((a,i)=>a.id=m.id+"_g"+i);M.maud(m,"Meeting scheduled",(ser?"Series of "+n+". ":"")+m.inv.length+" invited");if(!first)first=m}
 M.sync();S.meet.draft=null;S.meet.cur=first.dt;toast((n>1?n+" meetings":"Meeting")+" scheduled for "+fdw(first.dt),"good");go("meet_hub");S.v.meet=1;render();setTimeout(()=>M.open(first.id),80)}

/* ---------- record drawer hook: meetings, actions and decisions on projects, strategy items, incidents and changes ---------- */
M.recLinks=function(rec){const mt=M.meetings().filter(m=>(m.links||[]).some(l=>l.k===rec.k&&l.id===rec.id)||(rec.k==="project"&&M.projOf(m)===rec.id&&!(m.links||[]).some(l=>l.k==="project")&&false));
 const ids=new Set(mt.map(m=>m.id)),A=M.allActs().filter(a=>(a.link&&a.link.id===rec.id)||ids.has(a.mid)),D=M.allDecs().filter(d=>(d.links||[]).some(l=>l.id===rec.id)||ids.has(d.mid));if(!mt.length&&!A.length&&!D.length)return "";
 const grp=[];if(mt.length)grp.push({key:"m",label:"Meetings",rows:mt.sort((a,b)=>a.dt<b.dt?1:-1).map(m=>({id:m.id,t:m.t,sub:fd(m.dt)+" · "+M.TYPES[m.type].n,tag:m.st==="done"?"Held":"Next",st:"info",go:()=>{closeDrawer();M.open(m.id)}}))});
 if(A.length)grp.push({key:"a",label:"Actions",rows:A.sort((a,b)=>M.isOpenA(a)===M.isOpenA(b)?(a.due<b.due?-1:1):M.isOpenA(a)?-1:1).map(a=>({id:a.id,t:a.t,sub:a.own+" · due "+fd(a.due),tag:M.ST_A[a.st][0],st:M.isLate(a)?"bad":"info",go:()=>M.actDrawer(a.id)}))});
 if(D.length)grp.push({key:"d",label:"Decisions",rows:D.map(d=>({id:d.id,t:d.t,sub:d.by+" · "+fd(d.dt),tag:d.rat==="pending"?"Awaiting":"Decision",st:"info",go:()=>M.decDrawer(d.id)}))});
 return `<div class="eyebrow">Meetings, actions and decisions</div>`+lrHTML({id:"meet-rl-"+rec.k+rec.id,groups:grp,limit:4,search:true})};
function detectRec(d){const t=(d.textContent||"").slice(0,600);let x=t.match(/\b(INC|CHG|PRB|RITM)\d{4}\b/);if(x)return {k:{INC:"incident",CHG:"change",PRB:"problem",RITM:"request"}[x[1]],id:x[0]};
 const h=d.querySelector("h2,h1,h3");const ht=h?h.textContent.trim():"";if(!ht)return null;const p=PROJ.find(p=>p.n===ht);if(p)return {k:"project",id:p.id};
 const nodes=["O1","O2","O3","O4","O5"];const o=[["O1","Modernize standards publishing"],["O2","Reduce operating risk"],["O3","Protect revenue through contract discipline"],["O4","Trusted AI"],["O5","Improve editor and reviewer experience"]].find(x=>x[1]===ht);if(o)return {k:"objective",id:o[0]};
 const n=(window.NODES||[]).find(n=>n.n===ht&&(n.t==="proj"||n.t==="obj"));if(n)return {k:n.t==="obj"?"objective":"project",id:n.id};return null}
let hookT=0;function hook(){const d=q$("#drawer");if(!d||!d.children.length||d.querySelector(".meet-pg,.meet-comp,.meet-lk"))return;const rec=detectRec(d);if(!rec)return;const html=M.recLinks(rec);if(!html)return;const w=document.createElement("div");w.className="meet-lk";w.style.marginTop="18px";w.innerHTML=html;d.appendChild(w)}
(function arm(){const d=document.getElementById("drawer");if(!d){setTimeout(arm,300);return}new MutationObserver(()=>{clearTimeout(hookT);hookT=setTimeout(hook,80)}).observe(d,{childList:true})})();

/* ---------- events ---------- */
document.addEventListener("click",e=>{const t=e.target.closest("[data-mt]");if(!t)return;const v=t.dataset.mt.split("|"),k=v[0];const m=M.mById(v[1]);
 const fin=()=>{M.sync();repaint()};
 if(k==="open"){M.open(v[1]);return}
 if(k==="compose"){M.compose();return}
 if(k==="lk"){M.linkGo({k:v[1],id:v[2]});return}
 if(k==="ag-timer"){const tmr=S.meet.tm&&S.meet.tm.mid===v[1]?S.meet.tm:(S.meet.tm={mid:v[1],run:null,t0:0,acc:{}});const i=+v[2];if(tmr.run!=null){tmr.acc[tmr.run]=elapsed(tmr.run);const was=tmr.run;tmr.run=null;if(was!==i){tmr.run=i;tmr.t0=Date.now()}}else{tmr.run=i;tmr.t0=Date.now()}paint();return}
 if(k==="ag-done"){const g=m.agenda[+v[2]];g.st=g.st==="done"?"todo":"done";if(S.meet.tm&&S.meet.tm.run===+v[2]){S.meet.tm.acc[+v[2]]=elapsed(+v[2]);S.meet.tm.run=null}M.maud(m,"Agenda item "+(g.st==="done"?"completed":"reopened"),g.t);paint();return}
 if(k==="ag-del"){const g=m.agenda.splice(+v[2],1)[0];M.maud(m,"Agenda item removed",g.t);paint();return}
 if(k==="ag-add"){agForm(m);return}
 if(k==="agenda-tpl"){M.fillAgenda(m,0);M.maud(m,"Agenda drafted from template",T[m.type].n);toast("Agenda drafted. Check the owners and times.","info");fin();return}
 if(k==="prep"){m.prep={at:"Oct 6 "+tm(M.NOWH),conf:.85};M.maud(m,"Prep brief drafted","First Officer");toast("Prep brief drafted","info");fin();return}
 if(k==="start"){m.live=true;S.meet.tm={mid:m.id,run:0,t0:Date.now(),acc:{}};m.inv.forEach(i=>{if(i.rsvp==="yes"&&!i.att)i.att="present"});M.maud(m,"Meeting started",quorumView(m).met?"Quorum met":"Quorum not met");paint();return}
 if(k==="end"){m.live=false;m.st="done";if(S.meet.tm&&S.meet.tm.mid===m.id){S.meet.tm.run=null}m.minutes={st:"draft",by:m.secy||m.chair,at:TODAY,text:M.minutesText(m)};if(!m.sum)m.sum="Held "+fd(m.dt)+" with "+m.inv.filter(i=>i.att==="present").length+" attendees.";M.maud(m,"Meeting ended","Minutes drafted");toast("Meeting ended. Minutes drafted for review.","good");fin();return}
 if(k==="resched"){M.resched(v[1]);return}
 if(k==="cancel"){cancelForm(m);return}
 if(k==="edit"){editForm(m);return}
 if(k==="file-add"){fileForm(m);return}
 if(k==="copy-meet"){M.compose({type:m.type,title:m.t,people:m.inv.filter(i=>i.role!=="info").map(i=>i.n)});return}
 if(k==="att"){const i=m.inv[+v[2]];i.att=i.att===v[3]?null:v[3];if(v[3]==="delegate"&&i.att==="delegate"){dlgForm(m,+v[2]);return}M.maud(m,"Attendance recorded",i.n+": "+(i.att||"cleared"));fin();return}
 if(k==="dlg"){dlgForm(m,+v[2]);return}
 if(k==="inv-del"){const i=m.inv.splice(+v[2],1)[0];m.att=m.inv.map(x=>x.n);M.maud(m,"Invitee removed",i.n);fin();return}
 if(k==="ins"){const ta=document.getElementById("meet-notes");if(!ta)return;const s=ta.selectionStart||ta.value.length;const pre=ta.value.slice(0,s),post=ta.value.slice(s);const nl=(pre&&!pre.endsWith("\n"))?"\n":"";ta.value=pre+nl+v[2]+post;ta.focus();const pos=(pre+nl+v[2]).length;ta.setSelectionRange(pos,pos);m.nt=ta.value;const det=q$("[data-meet-det]");if(det)det.textContent=detectHTML(detect(m.nt));return}
 if(k==="extract"){const p=parseNotes(m);m.prop=(m.prop||[]).filter(x=>!p.some(y=>y.txt===x.txt)).concat(p);M.maud(m,"AI extraction",p.length+" items proposed");toast(p.length?p.length+" items proposed. Review each one.":"Nothing new found in the notes.","info");paint();return}
 if(k==="acc"||k==="acc-all"){const list=k==="acc"?m.prop.filter(p=>p.id===v[2]):m.prop.filter(p=>p.conf>=.85);list.forEach(p=>{if(p.kind==="Action")M.addAction(m,{t:p.txt,own:p.own||m.chair,due:p.due||addD(TODAY,7),src:"ai",conf:p.conf});else if(p.kind==="Decision")M.addDecision(m,{t:p.txt,why:"Recorded from the meeting notes.",src:"ai",conf:p.conf,by:m.chair});else{const a=M.addAction(m,{t:"Assess risk: "+p.txt,own:m.chair,due:addD(TODAY,7),src:"ai",conf:p.conf});M.toRaid("act",a.id)}});m.prop=m.prop.filter(p=>!list.includes(p));toast(list.length+" accepted","good");fin();return}
 if(k==="rej"){const p=m.prop.find(x=>x.id===v[2]);m.prop=m.prop.filter(x=>x.id!==v[2]);M.maud(m,"AI proposal rejected",p?p.txt:"");fin();return}
 if(k==="sum"){const heads=(m.nt.match(/^#\s.+$/gm)||[]).map(h=>h.slice(2));const a=M.allActs().filter(x=>x.mid===m.id),d=M.allDecs().filter(x=>x.mid===m.id);m.sum=(heads.length?"Covered "+heads.slice(0,4).join(", ").toLowerCase()+". ":"")+(d.length?d.length+" decision"+(d.length>1?"s":"")+": "+d[0].t.charAt(0).toLowerCase()+d[0].t.slice(1)+". ":"No decisions recorded. ")+(a.length?a.length+" action"+(a.length>1?"s":"")+" assigned, mostly to "+[...new Set(a.map(x=>x.own.split(" ")[0]))].slice(0,3).join(", ")+".":"No actions assigned.");M.maud(m,"Summary written","AI");fin();return}
 if(k==="add-act"){actForm(m);return}
 if(k==="add-dec"){decForm(m);return}
 if(k==="act-st"){M.setAction(v[1],v[2]);fin();if(S.meet.sel==null)M.actDrawer(v[1]);return}
 if(k==="act-done"){if(S.meet.sel==null&&q$("#drawer")&&q$("#drawer").matches(":popover-open"))M.actDrawer(v[1]);return}
 if(k==="act-raid"){const r=M.toRaid("act",v[1]);toast("Added to the RAID log as "+r,"good");fin();if(S.meet.sel==null)M.actDrawer(v[1]);return}
 if(k==="dec-raid"){const r=M.toRaid("dec",v[1]);toast("Added to the RAID log as "+r,"good");fin();if(S.meet.sel==null)M.decDrawer(v[1]);return}
 if(k==="dec-rat"){if(S.meet.sel==null&&q$("#drawer")&&q$("#drawer").matches(":popover-open")){M.decDrawer(v[1])}return}
 if(k==="carry"){const c=M.carryOver(v[1]);if(c){toast("Carried to the next meeting as "+c.id,"good");fin()}return}
 if(k==="lk-add"){m.links.push({k:v[2],id:v[3]});M.maud(m,"Link added",v[2]+" "+v[3]);S.meet.lkq="";paint();return}
 if(k==="lk-del"){const l=m.links.splice(+v[2],1)[0];M.maud(m,"Link removed",l.id);paint();return}
 if(k==="min-draft"){m.minutes={st:"draft",by:m.secy||m.chair,at:TODAY,text:M.minutesText(m)};M.maud(m,"Minutes drafted","AI from notes");fin();return}
 if(k==="min-submit"){m.minutes.st="review";M.maud(m,"Minutes sent for approval",m.chair);fin();return}
 if(k==="min-back"){m.minutes.st="draft";M.maud(m,"Changes requested on minutes",m.chair);fin();return}
 if(k==="min-approve"){m.minutes=Object.assign(m.minutes,{st:"published",appr:m.chair,apprAt:TODAY,dist:m.inv.filter(i=>i.role!=="info").map(i=>i.n)});M.maud(m,"Minutes approved and published","Sent to "+m.minutes.dist.length+" people and attached to "+(m.links||[]).length+" linked records");toast("Minutes published","good");fin();return}
 if(k==="copy"){try{navigator.clipboard.writeText(M.followUp(m));toast("Email copied","good")}catch(x){toast("Select the text and copy it","warn")}return}
 if(k==="ser-edit"){serForm(M.serById(v[1]));return}
 if(k==="ser-next"){const s=M.serById(v[1]);M.compose({type:s.type,title:s.n,people:s.mem.map(x=>x[0]),room:s.room,s:s.s});return}
 if(k==="rs-scope"){S.meet.rs.scope=v[1];S.meet.rsPaint();return}
 if(k==="rs-no"){closeDrawer();render();return}
 if(k==="rs-go"){const r=S.meet.rs,mm=M.mById(r.id),delta=dOf(r.dt)-dOf(mm.dt);if(r.scope==="all"&&mm.series){M.meetings().filter(x=>x.series===mm.series&&x.st==="next"&&x.dt>=mm.dt&&!x.cancel).forEach(x=>M.reschedule(x.id,addD(x.dt,delta),r.s))}else M.reschedule(r.id,r.dt,r.s);toast("Rescheduled. Invitees are notified.","good");closeDrawer();render();return}
 if(k==="df-type"){const d=S.meet.draft,Tm=T[v[1]];const oldT=T[d.type];if(d.title===oldT.n||!d.title)d.title=Tm.n;d.type=v[1];d.dur=Tm.dur;d.ag=Tm.ag.map(a=>({t:a[0],min:a[1],own:d.inv[0].n}));paintComposer();return}
 if(k==="df-dur"){S.meet.draft.dur=+v[1];paintComposer();return}
 if(k==="df-rep"){S.meet.draft.rep=v[1];paintComposer();return}
 if(k==="df-role"){S.meet.draft.inv[+v[1]].role=v[2];paintComposer();return}
 if(k==="df-del"){S.meet.draft.inv.splice(+v[1],1);paintComposer();return}
 if(k==="df-agdel"){S.meet.draft.ag.splice(+v[1],1);paintComposer();return}
 if(k==="df-agadd"){const d=S.meet.draft;d.ag.push({t:"New item",min:10,own:d.inv[0].n});paintComposer();return}
 if(k==="df-lkadd"){const d=S.meet.draft;d.links.push({k:v[1],id:v[2]});S.meet.lkq="";paintComposer();return}
 if(k==="df-lkdel"){S.meet.draft.links.splice(+v[1],1);paintComposer();return}
 if(k==="df-prep"){S.meet.draft.prep=!S.meet.draft.prep;paintComposer();return}
 if(k==="df-cancel"){S.meet.draft=null;closeDrawer();return}
 if(k==="df-go"){createFromDraft();return}
});
document.addEventListener("input",e=>{const t=e.target.closest("[data-mt-in]");if(!t)return;const v=t.dataset.mtIn.split("|"),k=v[0],m=M.mById(v[1]);
 if(k==="notes"){m.nt=t.value;const det=q$("[data-meet-det]");if(det)det.textContent=detectHTML(detect(m.nt));return}
 if(k==="agnote"){m.agenda[+v[2]].note=t.value;return}
 if(k==="lksearch"){const r=q$("[data-meet-lkres]");if(r)r.innerHTML=lkResults(m,t.value);return}
 if(k==="df"){S.meet.draft[v[1]]=t.value;return}
 if(k==="df-ag"){S.meet.draft.ag[+v[1]][v[2]]=v[2]==="min"?+t.value:t.value;return}
 if(k==="df-lks"){S.meet.lkq=t.value;const r=q$("[data-meet-dflk]");if(r)r.innerHTML=dfLinkRes(t.value);return}
});
document.addEventListener("change",e=>{const t=e.target.closest("[data-mt-ch]");if(!t)return;const v=t.dataset.mtCh.split("|"),k=v[0];
 if(k==="role"||k==="rsvp"){const m=M.mById(v[1]),i=m.inv[+v[2]];i[k]=t.value;M.maud(m,k==="role"?"Requirement changed":"RSVP recorded",i.n+": "+t.value);M.sync();paint();return}
 if(k==="rs-d"){S.meet.rs.dt=t.value;S.meet.rsPaint();return}
 if(k==="rs-t"){S.meet.rs.s=+t.value;S.meet.rsPaint();return}
 if(k==="df"){S.meet.draft[v[1]]=v[1]==="s"?+t.value:t.value;paintComposer();return}
 if(k==="df-ag"){S.meet.draft.ag[+v[1]][v[2]]=t.value;return}
 if(k==="df-file"){const f=t.files&&t.files[0];if(f){S.meet.draft.files.push(f.name);paintComposer()}return}
 if(k==="astatus"){return}
});
DND.on("meetag",(id,from,to,idx)=>{const mid=String(from).replace("ag:","");const m=M.mById(mid);if(!m)return;const i=m.agenda.findIndex(g=>g.id===id);if(i<0)return;const g=m.agenda.splice(i,1)[0];m.agenda.splice(Math.max(0,Math.min(m.agenda.length,idx>i?idx-1:idx)),0,g);M.maud(m,"Agenda reordered",g.t);paint()});
/* ratification from any list: update view */
document.addEventListener("click",e=>{const t=e.target.closest('[data-mt^="dec-rat"]');if(!t)return;setTimeout(()=>{if(S.meet.sel&&q$("#drawer")&&q$("#drawer").matches(":popover-open"))paint()},0)},false);
M.pageHTML=pageHTML;M.parseNotes=parseNotes;
})();
